(() => {
 const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
 const scenes=[
 ['THE MESSAGE','H1 wants to say hello to H2.','A message is broken into small pieces called packets. Follow the envelope.','The message is the cargo. Switches carry it; Ryu gives directions.','I choose the route.'],
 ['THE FIRST SWITCH','S1 checks: “Do I know the way?”','The first switch looks in its flow table. For this example, a matching forwarding rule is missing.','A flow table is a switch’s instruction list: match this traffic, then do this action.','Waiting for a question.'],
 ['ASK THE DECISION MAKER','“Ryu, where should this go?”','S1 sends a control message to Ryu. This Packet-In asks the controller to handle the unmatched packet.','Blue messages carry control information. They are different from the user’s packet.','Let me choose a route.'],
 ['SAVE THE DIRECTIONS','Ryu sends rules to the switches.','Ryu programs S1 and S2 with forwarding instructions. The switches store these entries in their flow tables.','Flow-Mod means “add or change a forwarding instruction.” The first packet also needs appropriate handling.','Save these instructions.'],
 ['DELIVER THE MESSAGE','Now the switches know the way.','Matching packets travel from H1 through S1 and S2 to H2. Watch the envelopes bypass Ryu.','Ryu decides. Switches forward. Matching packets do not visit Ryu every time.','The switches can handle this.'],
 ['CONNECT IT TO OUR RESEARCH','Record the traffic. Study the evidence.','Flow counters and other measurements join experiment logs and phase context. We build observations, then evaluate datasets and ML models.','Our research studies evidence from the network. The ML evaluation is a later pipeline, not the forwarding path.','Collect counters and context.']
 ];
 let scene=0,playing=false,moving=true,elapsed=0,clock=0,last=0,spoken=false;
 const film=q('#sdn-film');
 function stopSpeech(){if(spoken&&'speechSynthesis'in window){speechSynthesis.cancel();spoken=false;q('#sdn-story-speak').textContent='Read this step aloud';}}
 function controls(){q('#sdn-story-play').textContent=playing?'Pause story':elapsed||scene?'Continue story':'Play the 60-second story';q('#sdn-story-play').setAttribute('aria-pressed',playing);q('#sdn-story-back').disabled=scene===0;q('#sdn-story-next').disabled=scene===5;}
 function choose(i){stopSpeech();scene=i;clock=0;elapsed=0;film.dataset.scene=i;const d=scenes[i];q('#sdn-scene-count').textContent=`${String(i+1).padStart(2,'0')} / 06`;q('#sdn-scene-tag').textContent=d[0];q('#sdn-scene-title').textContent=d[1];q('#sdn-scene-line').textContent=d[2];q('#sdn-caption').textContent=d[3];q('#sdn-controller-speech').textContent=d[4];q('#sdn-command').textContent=i===2?'ASK RYU':i===5?'COUNTERS':'RULE';all('[data-sdn-scene]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.sdnScene===i));q('#sdn-story-progress').style.width=(i/6*100)+'%';controls();draw(0);}
 function manual(i){playing=false;moving=true;choose(i);q('.sdn-scene-lead').scrollIntoView({block:'start',behavior:reduceMotion.matches?'instant':'smooth'});q('#sdn-story-status').textContent=`Step ${i+1} of 6. The scene animates; use Next when you are ready.`;}
 all('[data-sdn-scene]').forEach(b=>b.addEventListener('click',()=>manual(+b.dataset.sdnScene)));
 q('#sdn-story-back').addEventListener('click',()=>manual(Math.max(0,scene-1)));q('#sdn-story-next').addEventListener('click',()=>manual(Math.min(5,scene+1)));q('#sdn-story-reset').addEventListener('click',()=>manual(0));
 q('#sdn-story-play').addEventListener('click',()=>{stopSpeech();if(playing){playing=false;moving=false;q('#sdn-story-status').textContent='Paused. Continue whenever you are ready.';}else{if(paused)setMotion(false);if(scene===5&&elapsed>=10000)choose(0);playing=true;moving=true;q('.sdn-scene-lead').scrollIntoView({block:'start',behavior:reduceMotion.matches?'instant':'smooth'});q('#sdn-story-status').textContent='Playing the six-step story. Each step lasts 10 seconds.';}controls();});
 q('#sdn-story-speak').addEventListener('click',()=>{if(!('speechSynthesis'in window)){q('#sdn-story-status').textContent='English speech is unavailable in this browser. The full explanation is shown in the captions.';return;}if(spoken){stopSpeech();return;}playing=false;controls();const u=new SpeechSynthesisUtterance(scenes[scene][1]+' '+scenes[scene][2]+' '+scenes[scene][3]);u.lang='en-US';u.rate=.92;const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('en'));if(voice)u.voice=voice;u.onend=()=>{spoken=false;q('#sdn-story-speak').textContent='Read this step aloud';};u.onerror=()=>{spoken=false;q('#sdn-story-speak').textContent='Read this step aloud';q('#sdn-story-status').textContent='Speech could not play here. Use the captions or try another browser.';};spoken=true;q('#sdn-story-speak').textContent='Stop reading';speechSynthesis.speak(u);});
 const paths={send:[[10,78],[30,56]],ask:[[30,56],[50,17]],rule1:[[50,17],[30,56]],rule2:[[50,17],[70,56]],delivery:[[10,78],[30,56],[70,56],[90,78]]};
 function at(points,u){let lengths=[],total=0;for(let i=1;i<points.length;i++){const d=Math.hypot(points[i][0]-points[i-1][0],points[i][1]-points[i-1][1]);lengths.push(d);total+=d;}let distance=Math.min(.9999,Math.max(0,u))*total;for(let i=0;i<lengths.length;i++){if(distance<=lengths[i]){const f=distance/lengths[i];return[points[i][0]+(points[i+1][0]-points[i][0])*f,points[i][1]+(points[i+1][1]-points[i][1])*f];}distance-=lengths[i];}return points[points.length-1];}
 function place(id,points,u){const [x,y]=at(points,u);q(id).style.left=x+'%';q(id).style.top=y+'%';}
 function draw(t){const u=(t%3400)/3400;place('#sdn-envelope',scene===4?paths.delivery:paths.send,scene===1?.98:u);place('#sdn-envelope-extra',paths.delivery,(u+.45)%1);place('#sdn-command',scene===3?paths.rule1:paths.ask,u);place('#sdn-command-extra',paths.rule2,u);const card=q('.sdn-rule-card');card.style.opacity=scene===3?Math.min(1,t/900):1;q('.sdn-received').style.opacity=scene===4&&u>.72?'1':'.25';}
 function frame(now){const dt=last?Math.min(70,now-last):0;last=now;const visible=location.hash==='#architecture'&&!document.hidden;const animate=visible&&!paused&&moving&&(!reduceMotion.matches||playing);film.classList.toggle('sdn-still',!animate);if(animate){clock+=dt;draw(clock);}if(playing&&visible&&!paused){elapsed+=dt;q('#sdn-story-progress').style.width=((scene+Math.min(1,elapsed/10000))/6*100)+'%';if(elapsed>=10000){if(scene<5)choose(scene+1);else{playing=false;moving=false;controls();q('#sdn-story-progress').style.width='100%';q('#sdn-story-status').textContent='Story complete. Ryu decides; switches forward. Replay or explore the technical view below.';}}}requestAnimationFrame(frame);}
 addEventListener('hashchange',()=>{if(location.hash!=='#architecture'){playing=false;stopSpeech();controls();}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSpeech();});choose(0);requestAnimationFrame(frame);
})();
